#!/bin/bash
#
# FORGE CLI Installer v1.1.8
# Self-contained -- no network calls, no git clone needed.
#
# Usage:
#   bash forge-install.sh                    # Install to ~/forge-cli/
#   bash forge-install.sh --dir /opt/forge   # Custom location
#   bash forge-install.sh --verbose          # Verbose output
#   bash forge-install.sh --update           # Reinstall/update
#

set -e

FORGE_VERSION="1.1.8"
DEFAULT_INSTALL_DIR="$HOME/forge-cli"

RED='\033[0;31m'; GREEN='\033[0;32m'; YELLOW='\033[1;33m'; CYAN='\033[0;36m'; NC='\033[0m'
log_info()    { echo -e "${CYAN}[i]${NC} $1"; }
log_success() { echo -e "${GREEN}[+]${NC} $1"; }
log_warning() { echo -e "${YELLOW}[!]${NC} $1"; }
log_error()   { echo -e "${RED}[-]${NC} $1"; }
log_verbose() { [[ $VERBOSE -eq 1 ]] && echo -e "    $1" || true; }

INSTALL_DIR="$DEFAULT_INSTALL_DIR"
VERBOSE=0
UPDATE=0

while [[ $# -gt 0 ]]; do
    case "$1" in
        --dir|-d)   INSTALL_DIR="$2"; shift 2 ;;
        --verbose|-v) VERBOSE=1; shift ;;
        --update|-u)  UPDATE=1; shift ;;
        --help|-h)
            echo ""; echo "FORGE CLI Installer v$FORGE_VERSION"
            echo "Usage: bash forge-install.sh [--dir <path>] [--verbose] [--update]"
            echo ""; exit 0 ;;
        *) log_error "Unknown argument: $1"; exit 1 ;;
    esac
done

echo ""; echo "========================================"; echo "FORGE CLI Installer v$FORGE_VERSION"; echo "========================================"
echo ""

if [[ -d \"$INSTALL_DIR\" ]]; then
    log_warning \"FORGE CLI already exists at: $INSTALL_DIR\"
    log_info \"Removing existing installation and reinstalling...\"
    rm -rf \"$INSTALL_DIR\"
fi

log_info "Installing to: $INSTALL_DIR"

TEMP_DIR="$(mktemp -d)"
trap "rm -rf $TEMP_DIR" EXIT

log_info "Extracting files..."
ARCHIVE="$TEMP_DIR/forge_cli.tar.gz"

echo "" | base64 -d > "$ARCHIVE"
log_verbose "Archive: $(wc -c < $ARCHIVE) bytes"

tar -xzf "$ARCHIVE" -C "$TEMP_DIR"
    rm -rf "$INSTALL_DIR"
    mv "$TEMP_DIR/forge_cli" "$INSTALL_DIR"

    # Strip carriage returns from shell scripts in case they were bundled on Windows
    for f in "$INSTALL_DIR"/*.sh "$INSTALL_DIR/forge"; do
        if [[ -f "$f" ]]; then
            tr -d '\r' < "$f" > "$f.tmp" && mv "$f.tmp" "$f"
        fi
    done

    chmod +x "$INSTALL_DIR/forge.sh" "$INSTALL_DIR/forge-in.sh" "$INSTALL_DIR/forge-out.sh" "$INSTALL_DIR/forge"
    chmod +x "$INSTALL_DIR/install-quick.sh" 2>/dev/null || true
    chmod +x "$INSTALL_DIR/uninstall.sh"     2>/dev/null || true

log_success "Files installed to: $INSTALL_DIR"
echo ""

detect_profile() {
    [[ -n "$ZSH_VERSION" ]]       && echo "$HOME/.zshrc"        && return
    [[ -f "$HOME/.bash_profile" ]] && echo "$HOME/.bash_profile" && return
    [[ -f "$HOME/.bashrc" ]]       && echo "$HOME/.bashrc"       && return
    echo "$HOME/.profile"
}

PROFILE="$(detect_profile)"
if grep -q "$INSTALL_DIR" "$PROFILE" 2>/dev/null; then
    log_info "Already in PATH"
else
    echo "" >> "$PROFILE"
    echo "# Added by FORGE CLI installer" >> "$PROFILE"
    echo "export PATH=\"\$PATH:$INSTALL_DIR\"" >> "$PROFILE"
    log_success "Added to PATH in $PROFILE"
fi

echo ""; echo "========================================"
log_success "FORGE CLI v$FORGE_VERSION installed!"
echo ""
echo "  1. Restart your terminal, or: source $PROFILE"
echo "  2. Try: forge help"
echo ""
echo "# PIXI INSTALL (coming soon)"
echo "# https://pixi.sh"
echo "========================================"
echo ""